from pptx import Presentation
p=Presentation('python学习指导.pptx')
out=[]
for i,s in enumerate(p.slides,1):
    out.append('===== Slide %d =====' % i)
    for sh in s.shapes:
        if sh.has_text_frame:
            txt=sh.text_frame.text.strip()
            if txt: out.append(txt.replace(chr(10),' / '))
        if sh.has_table:
            for r in sh.table.rows:
                out.append(' | '.join(c.text for c in r.cells))
open('preview.txt','w',encoding='utf-8').write(chr(10).join(out))
print('ok')
"; which soffice libreoffice 2>/dev/null; echo done

python -c "
from pptx import Presentation
from pptx.util import Emu
p=Presentation('python学习指导.pptx')
W,H=p.slide_width,p.slide_height
bad=[]
for i,s in enumerate(p.slides,1):
    for sh in s.shapes:
        try:
            if sh.left is None: continue
            if sh.left+sh.width>W+Emu(9525) or sh.top+sh.height>H+Emu(9525) or sh.left< -9525 or sh.top< -9525:
                bad.append((i, sh.shape_type, round(sh.left/914400,2), round(sh.top/914400,2), round((sh.left+sh.width)/914400,2), round((sh.top+sh.height)/914400,2)))
        except Exception as e: pass
print('out-of-bounds:', len(bad))
for b in bad: print(b)
"

